// Merges the Postgres lookup result with the upstream run context.
// Produces a single item per input with idem_decision in {NEW, POSTED, PENDING}.
const ctx = $('Merge Ingestion1').first().json;
const pgItems = $input.all();

let existing = null;
if (pgItems.length > 0 && pgItems[0].json && pgItems[0].json.id) {
  existing = pgItems[0].json;
}

let idem_decision = 'NEW';
if (existing) {
  if (existing.status === 'POSTED') idem_decision = 'POSTED';
  else if (existing.status === 'PENDING') idem_decision = 'PENDING';
  // FAILED falls through to NEW (allow reprocess)
}

return [{
  json: {
    ...ctx,
    idem_decision,
    existing_payout_uuid: existing ? existing.id : null,
    existing_xero_journal_id: existing ? existing.xero_journal_id : null,
  }
}];

// Decomposes a Stripe payout into journal lines using the account_map.
// THROWS on any unknown BT type — first real run surfaces gaps loudly.
const ctx = $('Resolve Idempotency1').item.json;
const payout = $('Fetch Stripe Payout1').item.json;
const btItems = $('Fetch Stripe Balance Transactions1').all();
const mapRows = $('Fetch Stripe Account Map1').all();

const accountMap = {};
for (const row of mapRows) {
  accountMap[row.json.transaction_type] = {
    code: row.json.xero_account_code,
    side: row.json.debit_or_credit,
    tmpl: row.json.description_template,
  };
}

if (btItems.length === 0) {
  throw new Error(`Empty Stripe balance transactions for payout ${ctx.payout_id} (workflow_run_id=${ctx.workflow_run_id})`);
}

const lines = [];
let gross = 0, fee = 0, refund = 0, adjustment = 0;

for (const item of btItems) {
  const bt = item.json;
  const map = accountMap[bt.type];
  if (!map) {
    throw new Error(`Unknown Stripe BT type: ${bt.type} (workflow_run_id=${ctx.workflow_run_id}, payout_id=${ctx.payout_id}, bt_id=${bt.id})`);
  }

  // Stripe amounts are signed integer minor units; absolute value goes into the line.
  const amountMinor = Math.abs(bt.amount);

  switch (bt.type) {
    case 'charge':
    case 'payment':
      gross += amountMinor;
      break;
    case 'refund':
    case 'payment_refund':
      refund += amountMinor;
      break;
    case 'stripe_fee':
      fee += amountMinor;
      break;
    case 'adjustment':
    case 'transfer':
      adjustment += amountMinor;
      break;
    case 'payout':
      // The payout BT itself is the net deposit; no category counter.
      break;
  }

  lines.push({
    account_code: map.code,
    debit_or_credit: map.side,
    amount_minor: amountMinor,
    description: map.tmpl.replace('{payout_id}', ctx.payout_id),
    transaction_type: bt.type,
    bt_id: bt.id,
  });
}

const netAmountMinor = Math.abs(payout.amount);

return [{
  json: {
    processor: 'stripe',
    payout_id: ctx.payout_id,
    workflow_run_id: ctx.workflow_run_id,
    payout_date: ctx.payout_date,
    source_trigger: ctx.source_trigger,
    received_at: ctx.received_at,
    lines,
    line_count: lines.length,
    gross_amount_minor: gross,
    net_amount_minor: netAmountMinor,
    fee_amount_minor: fee,
    refund_amount_minor: refund,
    adjustment_amount_minor: adjustment,
  }
}];

// Decomposes a Shopify payout into journal lines. Throws on unknown type or unmapped adjustment_reason.
const ctx = $('Resolve Idempotency1').item.json;
const payoutDetail = $('Fetch Shopify Payout Detail1').item.json.payout || $('Fetch Shopify Payout Detail1').item.json;
// Unwrap the response envelope. The HTTP node may return either:
// - one item with .json = {transactions: [...]} (envelope mode)
// - many items each with .json = a single transaction (auto-unwrapped mode)
const rawItems = $('Fetch Shopify Balance Transactions1').all();
let txItems;
if (rawItems.length === 1 && Array.isArray(rawItems[0].json.transactions)) {
  // Envelope mode: unwrap manually
  txItems = rawItems[0].json.transactions.map(t => ({ json: t }));
} else {
  // Already a list of transactions
  txItems = rawItems;
}
const mapRows = $('Fetch Shopify Account Map1').all();

const accountMap = {};
for (const row of mapRows) {
  accountMap[row.json.transaction_type] = {
    code: row.json.xero_account_code,
    side: row.json.debit_or_credit,
    tmpl: row.json.description_template,
  };
}

if (txItems.length === 0) {
  throw new Error(`Empty Shopify balance transactions for payout ${ctx.payout_id} (workflow_run_id=${ctx.workflow_run_id})`);
}
// Coerce string-or-numeric major units to integer minor units.
function toMinor(amount) {
  if (amount === null || amount === undefined) return 0;
  const n = typeof amount === 'number' ? amount : parseFloat(amount);
  if (Number.isNaN(n)) throw new Error(`Non-numeric Shopify amount: ${JSON.stringify(amount)}`);
  return Math.round(n * 100);
}

const lines = [];
let gross = 0, fee = 0, refund = 0, adjustment = 0;

for (const item of txItems) {
  const tx = item.json;
  // Adjustments carry an adjustment_reason; build the lookup key as adjustment_<reason>.
  const lookupKey = tx.type === 'adjustment' ? `adjustment_${tx.adjustment_reason}` : tx.type;
  const map = accountMap[lookupKey];
  if (!map) {
    throw new Error(`Unknown Shopify transaction key: ${lookupKey} (workflow_run_id=${ctx.workflow_run_id}, payout_id=${ctx.payout_id}, tx_id=${tx.id})`);
  }

  const amountMinor = Math.abs(toMinor(tx.amount));

  switch (tx.type) {
    case 'charge':
      gross += amountMinor;
      break;
    case 'refund':
      refund += amountMinor;
      break;
    case 'fee':
      fee += amountMinor;
      break;
    case 'adjustment':
      adjustment += amountMinor;
      break;
    case 'payout':
      // Payout BT itself is the net deposit
      break;
  }

  lines.push({
    account_code: map.code,
    debit_or_credit: map.side,
    amount_minor: amountMinor,
    description: map.tmpl.replace('{payout_id}', ctx.payout_id),
    transaction_type: lookupKey,
    tx_id: tx.id,
  });
}

const netAmountMinor = Math.abs(toMinor(payoutDetail.amount));

return [{
  json: {
    processor: 'shopify',
    payout_id: ctx.payout_id,
    workflow_run_id: ctx.workflow_run_id,
    payout_date: ctx.payout_date,
    source_trigger: ctx.source_trigger,
    received_at: ctx.received_at,
    lines,
    line_count: lines.length,
    gross_amount_minor: gross,
    net_amount_minor: netAmountMinor,
    fee_amount_minor: fee,
    refund_amount_minor: refund,
    adjustment_amount_minor: adjustment,
  }
}];

// Strict-fail validation. No rounding plug (Design Q3).
const data = $('Merge Decomposed1').item.json;
const lines = data.lines || [];

let totalDebits = 0, totalCredits = 0;
for (const line of lines) {
  if (line.debit_or_credit === 'debit') totalDebits += line.amount_minor;
  else if (line.debit_or_credit === 'credit') totalCredits += line.amount_minor;
  else throw new Error(`Line has invalid debit_or_credit: ${line.debit_or_credit} (workflow_run_id=${data.workflow_run_id}, payout_id=${data.payout_id})`);
}

if (totalDebits !== totalCredits) {
  const diff = totalDebits - totalCredits;
  throw new Error(JSON.stringify({
    check: 'unbalanced',
    expected: totalDebits,
    actual: totalCredits,
    diff,
    workflow_run_id: data.workflow_run_id,
    payout_id: data.payout_id,
    processor: data.processor,
  }));
}

// Forward input plus payout_uuid from Insert PENDING.
return [{
  json: {
    ...data,
    payout_uuid: $('Insert PENDING1').item.json.payout_uuid,
    validated: true,
    total_debits_minor: totalDebits,
    total_credits_minor: totalCredits,
  }
}];

// Build the Xero ManualJournal request body.
const data = $('Set Xero Tenant Id1').first().json;
const processorLabel = data.processor === 'stripe' ? 'Stripe' : 'Shopify';

const journalLines = data.lines.map(line => {
  const major = parseFloat((line.amount_minor / 100).toFixed(2));
  const signed = line.debit_or_credit === 'debit' ? major : -major;
  return {
    LineAmount: signed,
    AccountCode: line.account_code,
    Description: line.description,
  };
});

const journal = {
  Narration: `${processorLabel} payout ${data.payout_id} reconciliation`,
  Date: data.payout_date,
  Status: 'POSTED',
  JournalLines: journalLines,
};

return [{
  json: {
    ...data,
    xero_request_body: { ManualJournals: [journal] },
  }
}];

// Stripe webhook verification (structural, test-environment).
//
// IMPORTANT: True cryptographic HMAC verification is DEFERRED. n8n's Code-node
// sandbox blocks require('crypto') and require('node:crypto'), and the Webhook
// node on this plan/version delivers the body already parsed to JSON, so the
// byte-exact raw payload Stripe signed is not recoverable here. Cryptographic
// verification needs the raw body (N8N config / plan tier) at deployment. Until
// then this node performs STRUCTURAL verification: it confirms a Stripe-Signature
// header is present and well-formed, and that the body is a genuine Stripe event
// envelope. This proves the control point is wired; it is NOT a substitute for
// HMAC in production. Documented in ASSUMPTIONS.md.
//
// TODO(production): restore HMAC. Either (a) enable raw body and use the n8n
// Crypto node to HMAC-SHA256 the `${t}.${rawBody}` payload against the signing
// secret, or (b) verify upstream of n8n. Rotate the signing secret before any
// client demo. When restoring HMAC, also set ENFORCE_TIMESTAMP = true below.

// Set true in production to reject stale signatures (replay guard). Keep false
// while testing with pinned data, which is older than the 5-minute window.
const ENFORCE_TIMESTAMP = false;

const item = $input.first();
const headers = item.json.headers || {};

const sigHeader = headers['stripe-signature'] || headers['Stripe-Signature'];
if (!sigHeader) {
  throw new Error('Missing Stripe-Signature header');
}

const parts = Object.fromEntries(
  sigHeader.split(',').map(p => { const [k, ...v] = p.split('='); return [k, v.join('=')]; })
);
const timestamp = parts.t;
const signature = parts.v1;
if (!timestamp || !signature) {
  throw new Error('Malformed Stripe-Signature header');
}

if (ENFORCE_TIMESTAMP) {
  const tsSeconds = Number(timestamp);
  if (!Number.isFinite(tsSeconds)) {
    throw new Error('Malformed Stripe-Signature timestamp');
  }
  const ageSeconds = Math.floor(Date.now() / 1000) - tsSeconds;
  if (Math.abs(ageSeconds) > 300) {
    throw new Error(`Stripe-Signature timestamp outside tolerance (age ${ageSeconds}s)`);
  }
}

// The Webhook node delivers the parsed body at item.json.body.
const event = item.json.body;
if (!event || typeof event !== 'object') {
  throw new Error('Webhook body missing or not an object');
}
if (event.object !== 'event' || !event.type || !event.data || !event.data.object) {
  throw new Error('Body is not a well-formed Stripe event envelope');
}

// Output the EVENT at top level so downstream nodes read $json.data.object.* and
// $json.type directly (Filter to Paid Payout, Set Stripe Run Context).
return [{ json: event }];

const data = $('Validate Balance1').first().json;
return [{
  json: {
    ...data,
    tenantId: '1e8dfdcd-877f-4cf5-9a1b-bfd984b8c546',
  }
}];
